<?php
namespace App\Http\Controllers;
use App\Models\Category; use Illuminate\Http\Request;
class CategoryController extends Controller {public function index(){return view('categories.index',['categories'=>Category::withCount('books')->get()]);} public function create(){return view('categories.create');} public function store(Request $r){$d=$r->validate(['name'=>'required|unique:categories,name']);Category::create($d);return back()->with('success','Kategori berhasil ditambahkan.');} public function edit(Category $category){return view('categories.edit',compact('category'));} public function update(Request $r,Category $category){$d=$r->validate(['name'=>'required|unique:categories,name,'.$category->id]);$category->update($d);return redirect()->route('categories.index')->with('success','Kategori berhasil diperbarui.');} public function destroy(Category $category){if($category->books()->exists())return back()->with('error','Kategori masih memiliki buku.');$category->delete();return back()->with('success','Kategori berhasil dihapus.');}}
